(()=>{'use strict';const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');let s,timer=null,toastTimer;const maxHours=168;function fresh(){return{hour:0,wood:110,food:70,health:100,woodWorkers:3,foodWorkers:3,furnace:1,shelter:1,mill:1,hunt:1,power:1,over:false,logs:[]}}function day(){return Math.floor(s.hour/24)+1}function hour(){return (s.hour+6)%24}function night(){return hour()<6||hour()>=19}function storm(){return [3,5,7].includes(day())&&hour()>=12}function temp(){return -18-(night()?8:0)-(storm()?16:0)+(s.power&&s.wood>0?30+(s.furnace-1)*7+(s.power===2?14:0):0)+(s.shelter-1)*4}function rates(){let f=night()?.5:1;return{wood:s.woodWorkers*(3.2+(s.mill-1)*1.6)*f-s.power*2.5,food:s.foodWorkers*(2.4+(s.hunt-1)*1.2)*f-3}}function log(text){s.logs.unshift({at:`第 ${day()} 天 · ${String(hour()).padStart(2,'0')}:00`,text});s.logs=s.logs.slice(0,16)}function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2300)}function reset(){clearInterval(timer);timer=null;s=fresh();$('result').close();log('六个人，一座火炉。先确保食物与燃料，再强化营地。');render()}function finish(){s.over=true;clearInterval(timer);timer=null;const win=s.health>0&&s.furnace>=2&&s.shelter>=2;$('resultTitle').textContent=s.health<=0?'炉火熄灭，风雪未停':win?'风雪之后，便是家园':'活下来了，还需建设';$('resultText').textContent=s.health<=0?'营地没能挺过严寒或饥饿。下次请平衡分工，及早升级炉火和保温屋。':`你们共同度过了七天寒冬，村民健康 ${Math.ceil(s.health)}%。${win?'炉火和家园已准备好迎接新的幸存者。':'升级炉火与保温屋至 Lv.2，才能达成完整胜利。'}`;$('result').showModal()}
function advance(){if(s.over)return;const r=rates(),beforeStorm=storm();s.wood=Math.max(0,s.wood+r.wood);s.food=Math.max(0,s.food+r.food);const cold=temp();s.health=Math.min(100,Math.max(0,s.health+(cold<0?cold*.22:.5)+(s.food<=0?-4:0)+(6-s.woodWorkers-s.foodWorkers)*.2));s.hour++;if(storm()&&!beforeStorm)log('暴风雪来袭！开启强热，注意木材储备。');if(hour()===6)log(`清晨巡查：健康 ${Math.ceil(s.health)}%，储粮 ${Math.floor(s.food)}。`);if(s.health<=0||s.hour>=maxHours)finish();render()}
function upgrade(key,base,label){if(s.over)return;const cost=base*s[key];if(s[key]>=3)return;if(s.wood<cost)return toast('木材不足，请安排更多伐木工。');s.wood-=cost;s[key]++;log(`${label}升级至 Lv.${s[key]}。`);render()}
function render(){const r=rates(),t=temp();$('clock').textContent=`第 ${Math.min(day(),8)} 天 / 7 · ${String(hour()).padStart(2,'0')}:00`;$('wood').textContent=Math.floor(s.wood);$('food').textContent=Math.floor(s.food);$('temperature').textContent=`${t>0?'+':''}${t}°C`;$('temperature').style.color=t<0?'#91d0fc':'#ffc181';$('health').textContent=`${Math.ceil(s.health)}%`;$('woodRate').textContent=`${r.wood>=0?'+':''}${r.wood.toFixed(1)} / 小时 · 已扣炉火消耗`;$('foodRate').textContent=`${r.food>=0?'+':''}${r.food.toFixed(1)} / 小时 · 已扣村民消耗`;$('weather').textContent=storm()?'暴风雪 · 极寒预警':night()?'寒夜 · 生产效率降低':'晴雪 · 适合生产';$('weatherBadge').textContent=storm()?'❄ 暴风雪':night()?'☾ 漫长寒夜':'☀ 晴雪';$('idle').textContent=`闲置 ${6-s.woodWorkers-s.foodWorkers} 人`;$('woodWorkers').textContent=s.woodWorkers;$('foodWorkers').textContent=s.foodWorkers;$('furnaceLevel').textContent=`Lv.${s.furnace}`;$('heatInfo').textContent=`${s.power===0?'炉火已关闭':s.power===1?'节能供暖':'强热供暖'} · 每小时消耗 ${s.power*2.5} 木材`;
for(const [key,base,label,id] of [['furnace',80,'炉火','upgradeFurnace'],['shelter',65,'保温屋','upgradeShelter'],['mill',60,'伐木营地','upgradeMill'],['hunt',60,'狩猎小屋','upgradeHunt']]){const b=$(id);b.textContent=`${label} Lv.${s[key]} · ${s[key]>=3?'已满级':`升级 ${base*s[key]} 木材`}`;b.disabled=s.over||s[key]>=3||s.wood<base*s[key]}
document.querySelectorAll('[data-power]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.power)===s.power);b.disabled=s.over});document.querySelectorAll('[data-job]').forEach(b=>{const n=s[b.dataset.job+'Workers'];b.disabled=s.over||(Number(b.dataset.delta)<0?n===0:s.woodWorkers+s.foodWorkers>=6)});$('goalFurnace').textContent=`${s.furnace>=2?'✓':'○'} 炉火达到 Lv.2`;$('goalShelter').textContent=`${s.shelter>=2?'✓':'○'} 保温屋达到 Lv.2`;$('logs').innerHTML=s.logs.map(l=>`<div class="log"><small>${l.at}</small>${l.text}</div>`).join('');$('progress').style.width=`${Math.min(100,s.hour/maxHours*100)}%`;$('condition').textContent=t<0?'营地寒冷 · 健康下降':'营地温暖 · 健康恢复';$('forecast').textContent=storm()?'暴雪进行中 · 请保证供暖':'天气预报：第 3 / 5 / 7 天午后暴雪';$('pause').textContent=timer?'Ⅱ 暂停时间':'▶ 自动推进';$('pause').disabled=s.over;$('advance').disabled=s.over;draw(performance.now())}
document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{if(b.disabled)return;s[b.dataset.job+'Workers']+=Number(b.dataset.delta);render()});document.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>{s.power=Number(b.dataset.power);render()});$('upgradeFurnace').onclick=()=>upgrade('furnace',80,'炉火');$('upgradeShelter').onclick=()=>upgrade('shelter',65,'保温屋');$('upgradeMill').onclick=()=>upgrade('mill',60,'伐木营地');$('upgradeHunt').onclick=()=>upgrade('hunt',60,'狩猎小屋');$('advance').onclick=advance;$('pause').onclick=()=>{if(timer){clearInterval(timer);timer=null}else timer=setInterval(advance,1100);render()};$('restart').onclick=reset;$('again').onclick=reset;
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill()}function tree(x,y,z){ctx.fillStyle='#365468';ctx.fillRect(x-4*z,y,8*z,32*z);for(let i=0;i<3;i++){polygon([[x,y-65*z+i*20*z],[x-(24+i*5)*z,y-12*z+i*20*z],[x+(24+i*5)*z,y-12*z+i*20*z]],'#2f5365');polygon([[x,y-65*z+i*20*z],[x-(20+i*4)*z,y-24*z+i*20*z],[x+(18+i*4)*z,y-24*z+i*20*z]],'#b0d1de')}}function house(x,y,color,name,level){ctx.fillStyle='#476579';ctx.beginPath();ctx.ellipse(x,y+55,90,28,0,0,Math.PI*2);ctx.fill();polygon([[x-60,y],[x+55,y+15],[x+55,y+66],[x-60,y+49]],color);polygon([[x+55,y+15],[x+86,y-7],[x+86,y+43],[x+55,y+66]],'#344b5c');polygon([[x-78,y],[x-10,y-60],[x+100,y-10],[x+50,y+22]],'#d3e5ea');polygon([[x-78,y],[x+50,y+22],[x+50,y+31],[x-78,y+9]],'#89a9ba');ctx.fillStyle='#f4ba72';ctx.fillRect(x-40,y+15,20,19);ctx.fillRect(x+9,y+26,20,19);ctx.fillStyle='#293f52';ctx.fillRect(x-8,y+23,14,33);ctx.font='18px "Microsoft YaHei"';ctx.textAlign='center';ctx.fillStyle='#cfdfeb';ctx.fillText(name+' · '+level,x+10,y+97)}
function draw(time){if(!s)return;const w=1100,h=820;ctx.clearRect(0,0,w,h);const bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,night()?'#102235':'#29465a');bg.addColorStop(1,'#172c3e');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);polygon([[0,390],[180,65],[340,270],[480,80],[700,390]],'#375669');polygon([[120,175],[180,65],[245,176],[199,148],[165,188]],'#7b9baa');polygon([[510,390],[765,45],[980,270],[1100,180],[1100,550]],'#3e5d70');polygon([[691,143],[765,45],[837,129],[796,114],[761,151]],'#90abba');ctx.fillStyle='#57788b';ctx.beginPath();ctx.ellipse(550,490,510,258,0,0,7);ctx.fill();ctx.fillStyle='#6e90a0';ctx.beginPath();ctx.ellipse(550,470,488,244,0,0,7);ctx.fill();for(let i=0;i<17;i++){const a=i*2.399;tree(550+Math.cos(a)*440,450+Math.sin(a)*190,.7+(i%3)*.13)}ctx.strokeStyle='#9fb5bf';ctx.lineWidth=26;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(265,435);ctx.lineTo(570,510);ctx.lineTo(805,450);ctx.moveTo(570,510);ctx.lineTo(650,650);ctx.moveTo(570,510);ctx.lineTo(550,338);ctx.stroke();house(300,416,'#705d50','伐木营地',s.mill);house(795,433,'#645c58','狩猎小屋',s.hunt);house(598,290,'#64757b','保温屋',s.shelter);
const cx=548,cy=532;if(s.power&&s.wood>0){const glow=ctx.createRadialGradient(cx,cy,20,cx,cy,160);glow.addColorStop(0,'#ffb95b88');glow.addColorStop(1,'#ffb95b00');ctx.fillStyle=glow;ctx.fillRect(cx-160,cy-160,320,320)}ctx.fillStyle='#365161';ctx.beginPath();ctx.ellipse(cx,cy+36,69,28,0,0,7);ctx.fill();polygon([[cx-45,cy-65],[cx+35,cy-45],[cx+35,cy+40],[cx-45,cy+23]],'#806149');polygon([[cx+35,cy-45],[cx+65,cy-72],[cx+65,cy+13],[cx+35,cy+40]],'#4f4944');polygon([[cx-57,cy-70],[cx+3,cy-100],[cx+77,cy-73],[cx+35,cy-39]],'#a9b2af');ctx.fillStyle='#282f34';ctx.fillRect(cx-28,cy-25,39,47);if(s.power&&s.wood>0){polygon([[cx-20,cy+18],[cx-24,cy-6],[cx-9,cy-34-Math.sin(time/180)*8],[cx-4,cy-7],[cx+7,cy-19],[cx+8,cy+18]],'#ff9d45');polygon([[cx-14,cy+18],[cx-6,cy-11],[cx+2,cy+18]],'#ffe09a');for(let i=0;i<5;i++){const f=((time/26+i*30)%145);ctx.fillStyle=`rgba(202,219,225,${.22*(1-f/145)})`;ctx.beginPath();ctx.arc(cx+5+Math.sin(f/30)*18,cy-110-f,9+f/8,0,7);ctx.fill()}}ctx.textAlign='center';ctx.font='bold 19px "Microsoft YaHei"';ctx.fillStyle='#ffe0b0';ctx.fillText('中央炉火 · '+s.furnace,cx,cy+78);
for(let i=0;i<6;i++){const a=time/6000+i*1.05,x=550+Math.cos(a)*115,y=514+Math.sin(a)*59;ctx.fillStyle=i%2?'#b97249':'#48697d';ctx.fillRect(x-5,y-9,10,17);ctx.fillStyle='#e3c5a3';ctx.beginPath();ctx.arc(x,y-12,5,0,7);ctx.fill();ctx.fillStyle='#273d4a';ctx.fillRect(x-7,y-18,14,5)}const n=storm()?155:48;for(let i=0;i<n;i++){const x=(i*97+(time/(storm()?7:24)))%w,y=(i*137+time/(storm()?10:33))%h;ctx.fillStyle=storm()?'#dcebf3aa':'#dcebf366';ctx.beginPath();ctx.arc(x,y,i%3+1,0,7);ctx.fill()}if(storm()){ctx.fillStyle='#bcd7e21a';ctx.fillRect(0,0,w,h)}}
window.frostState=()=>JSON.parse(JSON.stringify({...s,temperature:temp(),storm:storm()}));let last=0;function frame(t){if(t-last>40){draw(t);last=t}requestAnimationFrame(frame)}reset();requestAnimationFrame(frame);
})();
